import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import MapComponent from './components/MapComponent';
import Login from './components/Login'; 
import PropertyList from './components/PropertyList';
import AiMatchmaker from './components/AiMatchmaker';
import OwnerDashboard from './components/OwnerDashboard';

const Home = () => {
  // Map ke liye dynamic city state
  const [mapCity, setMapCity] = useState('Meerut');

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif", maxWidth: "1200px", margin: "0 auto" }}>

      {/* Page Header */}
      <div style={{ textAlign: "center", padding: "40px 0 20px 0" }}>
        <h1 style={{ color: "#4a3b52", fontSize: "2.8rem", margin: "0 0 10px 0" }}>
          Find Your Perfect Student Stay
        </h1>
        <p style={{ color: "#786d84", fontSize: "1.2rem", margin: 0 }}>
          AI-powered PG & Hostel recommendations tailored for you
        </p>
      </div>

      {/* AI Matchmaker Section */}
      <AiMatchmaker />

      <hr style={{ margin: "40px 0", border: "1px solid #e6d9ef" }} />

      {/* Properties List */}
      <PropertyList />

      <hr style={{ margin: "40px 0", border: "1px solid #e6d9ef" }} />

      {/* Dynamic Map Section */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: "20px", flexWrap: "wrap", gap: "10px" }}>
        <h3 style={{ color: "#80608f", fontSize: "2rem", margin: 0 }}>
          Explore PGs on Map
        </h3>

        {/* City Select Dropdown for Map */}
        <select 
          value={mapCity} 
          onChange={(e) => setMapCity(e.target.value)} 
          style={{ padding: '10px 15px', borderRadius: '8px', fontSize: '1rem', border: '1px solid #80608f', outline: 'none', cursor: 'pointer', backgroundColor: '#f4eff7' }}
        >
          <option value="Meerut">Meerut</option>
          <option value="Noida">Noida</option>
          <option value="Ghaziabad">Ghaziabad</option>
        </select>
      </div>

      {/* Yahan mapCity state pass ho rahi hai */}
      <MapComponent city={mapCity} />

    </div>
  );
};

function App() {
  return (
    <Router>
      <div style={{ backgroundColor: "#faf8fc", minHeight: "100vh" }}>
        <Navbar />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/owner" element={<OwnerDashboard />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
